[
  {
    "statement": "No evidence was captured on the effect of removing food sources as a control tool for Procambarus crayfish.",
    "citations": [
      "1033"
    ]
  },
  {
    "statement": "No evidence was captured on the effect of draining the waterway as a control tool for Procambarus crayfish.",
    "citations": [
      "1034"
    ]
  }
]

[
  {
    "statement": "Evidence sources report that no studies were found that evaluated the effects of using biocides or other chemicals to control non-native, invasive or other problematic species on subtidal benthic invertebrate populations.",
    "citations": [
      "2171"
    ]
  },
  {
    "statement": "Evidence sources also report that no studies were found that evaluated the effects of using biocides or other chemicals to control invasive or problematic species on marine and freshwater mammal populations.",
    "citations": [
      "2937"
    ]
  }
]

[
  {
    "statement": "Rotenone application successfully eradicated black bullhead in studies from the UK and USA.",
    "citations": [
      "1050"
    ]
  },
  {
    "statement": "One of two ponds treated with rotenone required two doses to eradicate black bullhead.",
    "citations": [
      "1050"
    ]
  },
  {
    "statement": "Evidence on rotenone-based fish removal reports effects on amphibians.",
    "citations": [
      "828"
    ]
  },
  {
    "statement": "The reported effects on amphibians include increases in species numbers, abundance or recruitment in several cases.",
    "citations": [
      "828"
    ]
  },
  {
    "statement": "The reported effects on amphibians also include some mortality in other cases.",
    "citations": [
      "828"
    ]
  },
  {
    "statement": "Sources on rotenone-based fish removal do not report outcomes for native invertebrate communities.",
    "citations": [
      "828"
    ]
  },
  {
    "statement": "No long-term invertebrate community impacts are described.",
    "citations": [
      "828"
    ]
  }
]

[
  {
    "statement": "A replicated, controlled study in Belgium reported that introducing northern pike led to a strong decline in bullfrog tadpole numbers.",
    "citations": [
      "1039"
    ]
  },
  {
    "statement": "Evidence on the direct removal of adult bullfrogs indicates low catchability with one double fyke net over 24 hours in small shallow ponds in Belgium.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "Evidence indicates a rapid bullfrog population rebound after intensive adult removal in the USA.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "One small USA study showed successful overnight capture of adult bullfrogs using a single floating trap.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "A significant reduction in recorded adult and juvenile bullfrogs occurred when metamorphosed individuals were shot before reproduction as part of a combination treatment in France.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "No cost data were reported in the studies on northern pike introduction or direct bullfrog removal.",
    "citations": []
  }
]

[
  {
    "statement": "No studies were found that directly and quantitatively tested electrofishing for reducing populations of invasive Ponto-Caspian gobies.",
    "citations": [
      "1067"
    ]
  },
  {
    "statement": "The effectiveness of electrofishing for reducing populations of invasive Ponto-Caspian gobies could not be assessed.",
    "citations": [
      "1067"
    ]
  },
  {
    "statement": "The potential harmful impacts of electrofishing for reducing populations of invasive Ponto-Caspian gobies could not be assessed.",
    "citations": [
      "1067"
    ]
  }
]

[
  {
    "statement": "No evidence was found for use of draining invaded waterbodies to reduce the population size of invasive bullheads.",
    "citations": [
      "1078"
    ]
  },
  {
    "statement": "No evidence was found for use of electrofishing to reduce the population size of invasive bullheads.",
    "citations": [
      "1079"
    ]
  }
]

[
  {
    "statement": "The action document on search and removal using sniffer dogs reports that no evidence was captured on the success of using sniffer dogs to remove red-eared terrapins.",
    "citations": [
      "1058"
    ]
  }
]
